package com.oms.order.service;

import org.junit.jupiter.api.*;
import java.util.*;
import static com.oms.order.service.OrderValues.*;
import static com.oms.order.service.ExchangeService.map;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

class PlatformExchangeServiceTest {
    ExchangeServiceTest fixture;
    PlatformExchangeService source;
    @BeforeAll static void start(){ExchangeServiceTest.start();}
    @BeforeEach void setup(){fixture=new ExchangeServiceTest();fixture.reset();ExchangeServiceTest.db.update("DELETE FROM oms_order_issue_event");ExchangeServiceTest.db.update("DELETE FROM oms_order_issue");source=new PlatformExchangeService(fixture.repo,fixture.service);}
    @AfterEach void cleanup(){for(String table:Arrays.asList("oms_platform_exchange_snapshot","oms_platform_exchange"))ExchangeServiceTest.db.update("DELETE FROM "+table);}
    long ingest(Map<String,Object> payload){return number(source.ingest("VERIFY",1,payload,"test"),"id");}
    long count(String table){return ExchangeServiceTest.db.queryForObject("SELECT COUNT(*) FROM "+table,Long.class);}
    @Test void syncKeepsIndependentSourceAndDoesNotCreateBusinessOrTouchStock(){long id=ingest(fixture.source());Map<String,Object> p=source.row("VERIFY",id,false);assertEquals("WAITING",p.get("conversion_state"));assertNull(p.get("business_exchange_id"));assertEquals(0,count("oms_exchange"));assertEquals(1,count("oms_order"));assertFalse(source.detail("VERIFY",id).containsKey("payload"));verifyNoInteractions(fixture.warehouse);}
    @Test void duplicateAndOlderVersionsDoNotOverwriteLatest(){long id=ingest(fixture.source());assertEquals("DUPLICATE",source.ingest("VERIFY",1,new TreeMap<>(fixture.source()),"test").get("outcome"));assertEquals(1,count("oms_platform_exchange_snapshot"));Map<String,Object> old=fixture.source();old.put("modified","2026-10-01 00:00:00");old.put("num",1);assertEquals("OLDER",source.ingest("VERIFY",1,old,"test").get("outcome"));assertEquals(2,number(source.row("VERIFY",id,false),"requested_quantity"));assertEquals(1,number(source.row("VERIFY",id,false),"version"));}
    @Test void invalidApplicationIsRetainedWithRawSnapshot(){Map<String,Object> bad=fixture.source();bad.put("num",0);long id=ingest(bad);assertEquals("INVALID",source.row("VERIFY",id,false).get("source_state"));assertEquals("FAILED",source.convert("VERIFY",id,"test").get("state"));assertTrue(text(source.snapshot("VERIFY",id,ExchangeServiceTest.db.queryForObject("SELECT id FROM oms_platform_exchange_snapshot",Long.class)),"payload").contains("123456"));assertEquals(0,count("oms_exchange"));}
    @Test void conversionCanResumeAfterOriginalOrderArrives(){ExchangeServiceTest.db.update("DELETE FROM oms_order_line");ExchangeServiceTest.db.update("DELETE FROM oms_order");long id=ingest(fixture.source());assertEquals("FAILED",source.convert("VERIFY",id,"test").get("state"));assertEquals(1,count("oms_platform_exchange"));ExchangeServiceTest.db.update("INSERT INTO oms_order_line(company_code,order_id,platform_oid,sku_sn,goods_name,quantity,payment,reserved_quantity) VALUES ('VERIFY',?,'987654321012345679','A','original',5,25,5)",fixture.order);ExchangeServiceTest.db.update("INSERT INTO oms_order(id,company_code,order_sn,channel_id,platform_order_id,platform_tid,inventory_status,payment,review_status) VALUES (?,'VERIFY','SO_EXCHANGE',1,?,'987654321012345678','RESERVED',25,'APPROVED')",fixture.order,fixture.platform);assertEquals("SUCCESS",source.convert("VERIFY",id,"test").get("state"));assertEquals(1,count("oms_exchange"));}
    @Test void conversionIsIdempotentAndNeverGuessesTargetSku(){long id=ingest(fixture.source());long b=number(source.convert("VERIFY",id,"test"),"id");assertEquals(b,number(source.convert("VERIFY",id,"test"),"id"));assertEquals(1,count("oms_exchange"));Map<String,Object> e=fixture.service.row("VERIFY",b,false);assertEquals("",e.get("target_sku"));assertEquals(id,number(e,"platform_exchange_id"));assertNull(e.get("approved_version"));verifyNoInteractions(fixture.warehouse);}
    @Test void updatedTermsKeepAdoptedPlanAndExecutedFacts(){long id=ingest(fixture.source()),b=number(source.convert("VERIFY",id,"test"),"id");fixture.service.review("VERIFY",b,fixture.review(b),"test");ExchangeServiceTest.db.update("UPDATE oms_exchange SET stock_request='{}' WHERE id=?",b);Map<String,Object> fresh=fixture.source();fresh.put("modified","2026-10-16 10:00:00");fresh.put("num",3);ingest(fresh);Map<String,Object> e=fixture.service.row("VERIFY",b,false);assertEquals("BLOCKED",e.get("state"));assertNotNull(e.get("stock_request"));assertEquals(2,number(ExchangeService.object(e.get("approved_snapshot")),"quantity"));assertEquals(3,number(source.row("VERIFY",id,false),"requested_quantity"));assertEquals(5,ExchangeServiceTest.db.queryForObject("SELECT shipped_quantity FROM oms_order_shipment_line",Long.class));}
    @Test void conflictKeepsAcceptedSourceAndRequiresNewTrustedVersion(){long id=ingest(fixture.source()),b=number(source.convert("VERIFY",id,"test"),"id");Map<String,Object> conflict=fixture.source();conflict.put("num",3);assertEquals("CONFLICT",source.ingest("VERIFY",1,conflict,"test").get("outcome"));assertEquals(2,number(source.row("VERIFY",id,false),"requested_quantity"));assertEquals("BLOCKED",fixture.service.row("VERIFY",b,false).get("state"));ingest(fixture.source());assertEquals("CONFLICT",source.row("VERIFY",id,false).get("source_state"));}
    @Test void closedApplicationWithoutBusinessIsSkipped(){Map<String,Object> closed=fixture.source();closed.put("status","4");long id=ingest(closed);assertEquals("SKIPPED",source.row("VERIFY",id,false).get("conversion_state"));assertEquals("SKIPPED",source.convert("VERIFY",id,"test").get("state"));assertEquals(0,count("oms_exchange"));}
    @Test void closedApplicationWithExecutionKeepsStockAndBusiness(){long id=ingest(fixture.source()),b=number(source.convert("VERIFY",id,"test"),"id");ExchangeServiceTest.db.update("UPDATE oms_exchange SET stock_request='{}' WHERE id=?",b);Map<String,Object> closed=fixture.source();closed.put("modified","2026-10-16 10:00:00");closed.put("status","4");ingest(closed);assertEquals("BLOCKED",fixture.service.row("VERIFY",b,false).get("state"));assertNotNull(fixture.service.row("VERIFY",b,false).get("stock_request"));assertEquals(b,number(source.row("VERIFY",id,false),"business_exchange_id"));}
    @Test void pendingSourceBlocksUnshippedGoodsBeforeConversionAndOrdinaryResume(){ExchangeServiceTest.db.update("UPDATE oms_order_shipment_line SET shipped_quantity=0");long id=ingest(fixture.source());assertFalse(OrderExchangeGuard.reason(fixture.repo,"VERIFY",fixture.order,false).isEmpty());assertFalse(OrderReviewPolicy.systemBlock(fixture.repo.raw("VERIFY",fixture.platform)).isEmpty());assertEquals(1,ExchangeServiceTest.db.queryForObject("SELECT COUNT(*) FROM oms_order_issue WHERE domain='PLATFORM_EXCHANGE' AND state='OPEN' AND blocking=1",Integer.class));OrderBusinessService workspace=new OrderBusinessService();org.springframework.test.util.ReflectionTestUtils.setField(workspace,"repository",fixture.repo);org.springframework.test.util.ReflectionTestUtils.setField(workspace,"catalog",fixture.catalog);assertEquals(1,workspace.list("VERIFY",1L,"","","","","",0,1,20,"","","","AFTER_SALE","","","").getTotal());ExchangeServiceTest.db.update("UPDATE oms_order SET manual_hold=0");assertThrows(IllegalArgumentException.class,()->OrderExchangeGuard.requireReady(fixture.repo,"VERIFY",fixture.order,true));Map<String,Object> closed=fixture.source();closed.put("modified","2026-10-16 10:00:00");closed.put("status","4");ingest(closed);assertTrue(OrderExchangeGuard.reason(fixture.repo,"VERIFY",fixture.order,false).isEmpty());}
    @Test void explicitInternalLinkReusesBusinessAndChangedApplicationBlocksIt(){long b=fixture.ingest(fixture.source());ExchangeServiceTest.db.update("UPDATE oms_exchange SET source_kind='INTERNAL',dispute_id=NULL WHERE id=?",b);long id=ingest(fixture.source());assertEquals("FAILED",source.convert("VERIFY",id,"test").get("state"));assertEquals(1,source.candidates("VERIFY",id).size());source.link("VERIFY",id,map("version",1,"exchange_id",b,"confirmed",true,"reason","same goods and actual source verified"),"test");assertEquals(b,number(source.convert("VERIFY",id,"test"),"id"));assertEquals(1,count("oms_exchange"));Map<String,Object> changed=fixture.source();changed.put("modified","2026-10-16 11:00:00");changed.put("num",3);ingest(changed);assertEquals("BLOCKED",fixture.service.row("VERIFY",b,false).get("state"));assertEquals(2,number(fixture.service.row("VERIFY",b,false),"requested_quantity"));}
    @Test void autoConversionRequiresItsOwnSwitchAndDoesNotApproveOrWritePlatform(){long id=ingest(fixture.source());source.autoConvert("VERIFY");assertEquals(0,count("oms_exchange"));ExchangeServiceTest.db.update("UPDATE oms_exchange_config SET auto_convert=1");source.autoConvert("VERIFY");source.autoConvert("VERIFY");assertEquals(1,count("oms_exchange"));long b=number(source.row("VERIFY",id,false),"business_exchange_id");assertNull(fixture.service.row("VERIFY",b,false).get("approved_version"));verifyNoInteractions(fixture.bridge,fixture.warehouse);}
    @Test void companyScopeAndFiltersNeverExposePayloadOrOtherCompany(){long id=ingest(fixture.source());assertThrows(IllegalArgumentException.class,()->source.detail("OTHER",id));assertThrows(IllegalArgumentException.class,()->source.convert("OTHER",id,"test"));long snap=ExchangeServiceTest.db.queryForObject("SELECT id FROM oms_platform_exchange_snapshot",Long.class);assertThrows(IllegalArgumentException.class,()->source.snapshot("OTHER",id,snap));assertEquals(0,number(source.list("OTHER",Collections.emptyMap()),"total"));assertEquals(1,number(source.list("VERIFY",Collections.singletonMap("number","123456")),"total"));assertEquals(0,number(source.list("VERIFY",Collections.singletonMap("state","SUCCESS")),"total"));assertFalse(source.list("VERIFY",Collections.emptyMap()).toString().contains("payload"));}
}
